-- @seq 70
CREATE FUNCTION public.acct_1099_export(p_tenant_id uuid, p_tax_year integer, p_form text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid) RETURNS TABLE(vendor_id uuid, vendor_name text, legal_name text, tin_type text, tin_last4 text, tin_on_file boolean, tin_vault_id text, tin_verified boolean, w9_on_file boolean, w9_request_status text, email text, mailing_address text, form text, box text, amount numeric, excluded_card_amount numeric, threshold numeric, must_file boolean, backup_withholding boolean, ready_to_file boolean, issues text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  RETURN QUERY
  SELECT s.vendor_id, s.vendor_name, v.legal_name, s.tin_type, v.tin_last4, s.tin_on_file, v.tin_vault_id::text,
         v.tin_verified_at IS NOT NULL, s.w9_on_file, inv.status, v.email, s.mailing_address, s.form, s.box,
         s.amount, s.excluded_card_amount, s.threshold, s.must_file, coalesce(v.backup_withholding, false),
         s.must_file AND iss.list = '{}'::text[],
         iss.list
    FROM acct_1099_summary(p_tenant_id, p_tax_year, p_entity_id) s
    JOIN acct_vendors v ON v.id = s.vendor_id
    LEFT JOIN LATERAL (SELECT ci.status FROM acct_contractor_invites ci WHERE ci.vendor_id = s.vendor_id ORDER BY ci.sent_at DESC NULLS LAST LIMIT 1) inv ON true
    CROSS JOIN LATERAL (SELECT array_remove(ARRAY[
         CASE WHEN NOT s.tin_on_file THEN 'Missing TIN' END,
         CASE WHEN NOT s.w9_on_file THEN 'Missing W-9' END,
         CASE WHEN coalesce(s.mailing_address,'') = '' THEN 'Missing mailing address' END,
         CASE WHEN coalesce(v.legal_name,'') = '' THEN 'Missing legal name' END,
         CASE WHEN s.tin_on_file AND v.tin_verified_at IS NULL THEN 'TIN not verified (IRS TIN matching)' END,
         CASE WHEN coalesce(v.backup_withholding,false) THEN 'Backup withholding applies' END], NULL) AS list) iss
   WHERE p_form IS NULL OR s.form = p_form
   ORDER BY s.form, s.box, s.vendor_name;
END $$;

-- @seq 71
CREATE FUNCTION public.acct_1099_summary(p_tenant_id uuid, p_tax_year integer, p_entity_id uuid DEFAULT NULL::uuid) RETURNS TABLE(vendor_id uuid, vendor_name text, tin_type text, tin_on_file boolean, w9_on_file boolean, mailing_address text, form text, box text, amount numeric, excluded_card_amount numeric, threshold numeric, must_file boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE v_from date := make_date(p_tax_year,1,1); v_to date := make_date(p_tax_year,12,31);
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  RETURN QUERY
  WITH pay AS (
    -- bill payments: allocate each payment across the bill's lines pro rata, so box comes from line > account > vendor
    SELECT p.vendor_id, coalesce(bl.form_1099_box, a.default_1099_box, v.default_1099_box, 'NEC-1') AS box,
           round(ap.applied_amount * bl.line_subtotal / nullif(b.subtotal,0), 2) AS amt,
           (r.account_kind IN ('credit_card','payment_processor') OR p.payment_method IN ('credit_card','debit_card')) AS via_card
      FROM acct_ap_payments p
      JOIN acct_ap_payment_applications ap ON ap.payment_id = p.id
      JOIN acct_ap_bills b ON b.id = ap.bill_id
      JOIN acct_ap_bill_lines bl ON bl.bill_id = b.id
      JOIN acct_chart_of_accounts a ON a.id = bl.expense_account_id
      JOIN acct_vendors v ON v.id = p.vendor_id
      LEFT JOIN acct_bank_accounts r ON r.id = p.cash_account_id
     WHERE p.tenant_id = p_tenant_id AND p.status <> 'void' AND p.payment_date BETWEEN v_from AND v_to
       AND (p_entity_id IS NULL OR p.entity_id = p_entity_id) AND v.is_1099_vendor
    UNION ALL
    -- direct expenses / checks
    SELECT s.payee_vendor_id, coalesce(sl.form_1099_box, a.default_1099_box, v.default_1099_box, 'NEC-1'), sl.amount + sl.tax_amount,
           (s.txn_kind IN ('cc_charge','cc_credit') OR r.account_kind IN ('credit_card','payment_processor'))
      FROM acct_spend_transactions s
      JOIN acct_spend_lines sl ON sl.spend_id = s.id
      JOIN acct_chart_of_accounts a ON a.id = sl.account_id
      JOIN acct_vendors v ON v.id = s.payee_vendor_id
      JOIN acct_bank_accounts r ON r.id = s.bank_account_id
     WHERE s.tenant_id = p_tenant_id AND s.status = 'posted' AND s.txn_kind <> 'cc_credit' AND s.payment_date BETWEEN v_from AND v_to
       AND (p_entity_id IS NULL OR s.entity_id = p_entity_id) AND v.is_1099_vendor
  ), agg AS (
    SELECT pay.vendor_id, pay.box, sum(pay.amt) FILTER (WHERE NOT pay.via_card) AS amt, coalesce(sum(pay.amt) FILTER (WHERE pay.via_card),0) AS card_amt
      FROM pay GROUP BY pay.vendor_id, pay.box
  )
  SELECT v.id, coalesce(v.display_name, v.legal_name), v.tin_type, (v.tin_vault_id IS NOT NULL OR v.tax_number IS NOT NULL), v.w9_received_at IS NOT NULL,
         acct_address_text('vendor', v.id, 'mailing'),
         CASE WHEN split_part(g.box,'-',1) = 'NEC' THEN '1099-NEC' ELSE '1099-MISC' END, split_part(g.box,'-',2),
         coalesce(g.amt,0), g.card_amt,
         acct_1099_threshold(CASE WHEN split_part(g.box,'-',1) = 'NEC' THEN '1099-NEC' ELSE '1099-MISC' END, split_part(g.box,'-',2), p_tax_year),
         coalesce(g.amt,0) >= coalesce(acct_1099_threshold(CASE WHEN split_part(g.box,'-',1) = 'NEC' THEN '1099-NEC' ELSE '1099-MISC' END, split_part(g.box,'-',2), p_tax_year), 600)
    FROM agg g JOIN acct_vendors v ON v.id = g.vendor_id
   ORDER BY 2, 7, 8;
END $$;

-- @seq 72
CREATE FUNCTION public.acct_1099_threshold(p_form text, p_box text, p_year integer) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  SELECT amount_threshold FROM acct_1099_thresholds
   WHERE form = p_form AND box = p_box AND tax_year_from <= p_year AND (tax_year_to IS NULL OR tax_year_to >= p_year)
   ORDER BY tax_year_from DESC LIMIT 1;
$$;

-- @seq 253
CREATE FUNCTION public.acct_payroll_run_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.gl_journal_entry_id IS NULL AND lower(coalesce(NEW.status,'')) IN ('processed','paid','completed','posted')
     AND acct_default_entity(NEW.tenant_id) IS NOT NULL THEN
    BEGIN
      PERFORM acct_post_payroll_run(NEW.id);
    EXCEPTION WHEN OTHERS THEN
      UPDATE acct_payroll_runs SET error_message = 'Ledger posting failed: ' || SQLERRM WHERE id = NEW.id;
    END;
  END IF;
  RETURN NULL;
END $$;

-- @seq 537
CREATE FUNCTION public.run_payroll(p_tenant_id uuid, p_number text, p_pay_period_start date, p_pay_period_end date, p_pay_date date, p_run_items jsonb, p_cash_account_id uuid, p_wage_account_id uuid DEFAULT NULL::uuid, p_tax_payable_account_id uuid DEFAULT NULL::uuid, p_employer_tax_account_id uuid DEFAULT NULL::uuid, p_employer_taxes numeric DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_run_id      uuid;
  v_item        jsonb;
  v_gross       numeric(18,4) := 0;
  v_tax         numeric(18,4) := 0;
  v_net         numeric(18,4) := 0;
  v_emp_taxes  numeric(18,4) := p_employer_taxes;
  v_lines       jsonb := '[]'::jsonb;
  v_journal_id  uuid;
  v_wage_acct   uuid := p_wage_account_id;
  v_tax_acct    uuid := p_tax_payable_account_id;
  v_emp_tax_acct uuid := p_employer_tax_account_id;
begin
  if p_run_items is null or jsonb_array_length(p_run_items) = 0 then
    raise exception 'No payroll run items provided';
  end if;

  if v_wage_acct is null then
    select id into v_wage_acct from chart_of_accounts
     where tenant_id = p_tenant_id and code = '5400' limit 1;
  end if;
  if v_tax_acct is null then
    select id into v_tax_acct from chart_of_accounts
     where tenant_id = p_tenant_id and code = '2200' limit 1;
  end if;
  if v_emp_tax_acct is null then
    select id into v_emp_tax_acct from chart_of_accounts
     where tenant_id = p_tenant_id and code = '5400' limit 1;  -- same wage expense for simplicity
  end if;
  if v_wage_acct is null or v_tax_acct is null then
    raise exception 'Missing wage or tax payable account. Seed standard chart of accounts.';
  end if;

  insert into payroll_runs (tenant_id, number, pay_period_start, pay_period_end, pay_date, status,
                             gross_wages, tax_withheld, net_paid, employer_taxes)
  values (p_tenant_id, p_number, p_pay_period_start, p_pay_period_end, p_pay_date, 'approved',
          0, 0, 0, p_employer_taxes)
  returning id into v_run_id;

  for v_item in select jsonb_array_elements(p_run_items) loop
    declare
      v_emp_id      uuid := (v_item->>'employee_id')::uuid;
      v_ts_id       uuid := nullif(v_item->>'timesheet_id','')::uuid;
      v_hrs_reg     numeric(18,4) := coalesce((v_item->>'hours_regular')::numeric, 0);
      v_hrs_ot      numeric(18,4) := coalesce((v_item->>'hours_overtime')::numeric, 0);
      v_gross_wages numeric(18,4) := coalesce((v_item->>'gross_wages')::numeric, 0);
      v_tax_withheld numeric(18,4) := coalesce((v_item->>'tax_withheld')::numeric, 0);
      v_net_paid    numeric(18,4) := coalesce((v_item->>'net_paid')::numeric, 0);
    begin
      v_gross := v_gross + v_gross_wages;
      v_tax := v_tax + v_tax_withheld;
      v_net := v_net + v_net_paid;

      insert into payroll_run_items (payroll_run_id, employee_id, timesheet_id,
                                       hours_regular, hours_overtime, gross_wages, tax_withheld, net_paid)
      values (v_run_id, v_emp_id, v_ts_id, v_hrs_reg, v_hrs_ot, v_gross_wages, v_tax_withheld, v_net_paid);

      if v_ts_id is not null then
        update payroll_timesheets set status = 'processed' where id = v_ts_id;
      end if;
    end;
  end loop;

  v_lines := v_lines || jsonb_build_array(jsonb_build_object(
    'account_id', v_wage_acct, 'debit', v_gross, 'credit', 0,
    'description', 'Gross wages — ' || p_number
  ));
  if v_tax > 0 then
    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'account_id', v_tax_acct, 'debit', 0, 'credit', v_tax,
      'description', 'Tax withheld — ' || p_number
    ));
  end if;
  v_lines := v_lines || jsonb_build_array(jsonb_build_object(
    'account_id', p_cash_account_id, 'debit', 0, 'credit', v_net,
    'description', 'Net pay — ' || p_number
  ));
  if v_emp_taxes > 0 then
    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'account_id', v_emp_tax_acct, 'debit', v_emp_taxes, 'credit', 0,
      'description', 'Employer taxes — ' || p_number
    ));
    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'account_id', v_tax_acct, 'debit', 0, 'credit', v_emp_taxes,
      'description', 'Employer tax payable — ' || p_number
    ));
  end if;

  v_journal_id := post_journal(
    p_tenant_id := p_tenant_id,
    p_entry_date := p_pay_date,
    p_lines := v_lines,
    p_memo := 'Payroll run ' || p_number,
    p_reference := p_number,
    p_source := 'payroll',
    p_source_id := v_run_id::text
  );

  update payroll_runs
     set gross_wages = v_gross,
         tax_withheld = v_tax,
         net_paid = v_net,
         employer_taxes = v_emp_taxes,
         journal_id = v_journal_id,
         status = 'posted'
   where id = v_run_id;

  return v_run_id;
end;
$$;

